-- =============================================================================
-- Seed de desenvolvimento local
-- Este arquivo existe para popular o Supabase local com dados previsiveis.
-- Nunca use este seed em staging ou producao.
-- =============================================================================

BEGIN;

-- ---------------------------------------------------------------------------
-- 1. Observacao sobre autenticacao local
-- ---------------------------------------------------------------------------
-- O usuario admin local e criado separadamente por scripts/seed-auth-local.sh.
-- Isso evita que mudancas internas do schema auth quebrem o `supabase start`.

-- ---------------------------------------------------------------------------
-- 2. Campeonato base
-- ---------------------------------------------------------------------------
INSERT INTO public.championships (
  id,
  name,
  season,
  status,
  points_win,
  points_draw,
  points_loss,
  periods_count,
  period_duration,
  teams_count,
  players_per_team,
  goalkeepers_per_team,
  waitlist_goalkeepers,
  waitlist_outfield,
  max_players,
  max_waitlist_players,
  created_at
)
-- SELECT, e nao VALUES, porque as duas ultimas grandezas SAEM das cinco
-- anteriores e uma linha de VALUES nao consegue se referenciar. O formato fica
-- escrito UMA vez, em `formato` logo abaixo, e a capacidade vem dele.
SELECT
  '10000000-0000-0000-0000-000000000001'::uuid,
  'Copa Local de Desenvolvimento',
  '2026',
  'active',
  3,
  1,
  0,
  2,
  7,
  formato.teams_count,
  formato.players_per_team,
  formato.goalkeepers_per_team,
  formato.waitlist_goalkeepers,
  formato.waitlist_outfield,
  -- As duas que ninguem digita, e que ate aqui o seed nao gravava: nasciam
  -- `max_players` NULL e `max_waitlist_players` 0, o default da coluna.
  --
  -- NULL nao e "nao configurado" para quem le: as duas RPCs tratam
  -- `v_max_players IS NULL` como ILIMITADO. Ou seja, um `local:reset` limpo
  -- entregava um campeonato com formato 8x10 gravado e NENHUM teto -- a
  -- capacidade que o A6 derivou existia so no `toRow` do formulario do admin,
  -- e portanto so depois de alguem abrir a tela e salvar.
  --
  -- A conta e a mesma de `derivedCapacity` (features/championships/capacity.ts):
  -- total = times x jogadores por time; espera = goleiros + linha na fila. Aqui
  -- ela cabe crua porque os cinco numeros abaixo sao literais positivos e
  -- inteiros -- nao ha o zero, o negativo nem o fracionario que a funcao prende.
  formato.teams_count * formato.players_per_team,
  formato.waitlist_goalkeepers + formato.waitlist_outfield,
  now()
-- O formato de 2026, igual ao de staging: 8 x 10 = 80 vagas, 8 de goleiro e 72
-- de linha, espera de 1 goleiro + 4 de linha. Sem isto o local nasce com
-- teams_count NULL e qualquer medida de capacidade feita aqui e irreproduzivel
-- -- foi o que aconteceu: o "8x10 da 80/8/72/5" foi medido contra estado
-- editado a mao, que um `local:reset` limpo apagava.
FROM (VALUES (8, 10, 1, 1, 4)) AS formato (
  teams_count,
  players_per_team,
  goalkeepers_per_team,
  waitlist_goalkeepers,
  waitlist_outfield
)
ON CONFLICT (id) DO UPDATE
SET
  name = EXCLUDED.name,
  season = EXCLUDED.season,
  status = EXCLUDED.status,
  points_win = EXCLUDED.points_win,
  points_draw = EXCLUDED.points_draw,
  points_loss = EXCLUDED.points_loss,
  periods_count = EXCLUDED.periods_count,
  period_duration = EXCLUDED.period_duration,
  teams_count = EXCLUDED.teams_count,
  players_per_team = EXCLUDED.players_per_team,
  goalkeepers_per_team = EXCLUDED.goalkeepers_per_team,
  waitlist_goalkeepers = EXCLUDED.waitlist_goalkeepers,
  waitlist_outfield = EXCLUDED.waitlist_outfield,
  max_players = EXCLUDED.max_players,
  max_waitlist_players = EXCLUDED.max_waitlist_players;

