INSERT INTO public.championship_registrations (
  id,
  championship_id,
  player_id,
  is_goalkeeper,
  final_overall,
  created_at
)
SELECT
  registration_id::uuid,
  '10000000-0000-0000-0000-000000000001'::uuid,
  player_id::uuid,
  -- O balde sai da COLUNA do seed, e nao de comparar `preferred_position` com
  -- uma grafia. O porque esta na nota da secao 5.
  is_goalkeeper,
  final_overall,
  now()
FROM player_seed
ON CONFLICT (id) DO UPDATE
SET
  championship_id = EXCLUDED.championship_id,
  player_id = EXCLUDED.player_id,
  is_goalkeeper = EXCLUDED.is_goalkeeper,
  final_overall = EXCLUDED.final_overall;

