-- ---------------------------------------------------------------------------
-- 9. Coerencia entre o formato e o que foi gravado
-- ---------------------------------------------------------------------------
-- Este bloco existe porque os dois furos que ele cobre nasceram calados, e
-- calados sobreviveram a um `local:reset` inteiro: o banco subia verde, com o
-- formato 8x10 gravado, capacidade ILIMITADA e oito goleiros contados como
-- zero. Nada falhava -- so a cota parava de existir.
--
-- Ele nao cita posicao. Confere o que foi GRAVADO contra o FORMATO, que e a
-- unica fonte: a capacidade contra times x jogadores por time, e o total de
-- baldes de goleiro contra times x goleiros por time. Se a grafia da posicao
-- mudar, isto continua valendo; se alguem mexer no elenco e esquecer a coluna
-- `is_goalkeeper`, isto para o seed em vez de deixar passar.
DO $$
DECLARE
  c record;
  v_goleiros int;
  v_inscritos int;
BEGIN
  SELECT teams_count, players_per_team, goalkeepers_per_team,
         waitlist_goalkeepers, waitlist_outfield,
         max_players, max_waitlist_players
    INTO c
    FROM public.championships
   WHERE id = '10000000-0000-0000-0000-000000000001';

  IF c.max_players IS DISTINCT FROM c.teams_count * c.players_per_team THEN
    RAISE EXCEPTION
      'seed incoerente: max_players e % e o formato % x % pede %',
      c.max_players, c.teams_count, c.players_per_team,
      c.teams_count * c.players_per_team;
  END IF;

  IF c.max_waitlist_players IS DISTINCT FROM
     c.waitlist_goalkeepers + c.waitlist_outfield THEN
    RAISE EXCEPTION
      'seed incoerente: max_waitlist_players e % e a fila % + % pede %',
      c.max_waitlist_players, c.waitlist_goalkeepers, c.waitlist_outfield,
      c.waitlist_goalkeepers + c.waitlist_outfield;
  END IF;

  SELECT count(*) FILTER (WHERE is_goalkeeper), count(*)
    INTO v_goleiros, v_inscritos
    FROM public.championship_registrations
   WHERE championship_id = '10000000-0000-0000-0000-000000000001';

  IF v_goleiros IS DISTINCT FROM c.teams_count * c.goalkeepers_per_team THEN
    RAISE EXCEPTION
      'seed incoerente: % inscricoes no balde de goleiro e o formato % x % pede %',
      v_goleiros, c.teams_count, c.goalkeepers_per_team,
      c.teams_count * c.goalkeepers_per_team;
  END IF;

  -- O elenco tambem tem de caber: 64 inscritos em 80 vagas deixa o campeonato
  -- aberto, que e o estado em que o local serve para testar inscricao.
  IF v_inscritos > c.max_players THEN
    RAISE EXCEPTION
      'seed incoerente: % inscricoes para % vagas',
      v_inscritos, c.max_players;
  END IF;
END
$$;

COMMIT;
